		{"http://127.0.0.1:30481", true},
		{"http://127.0.0.1", true},
		{"http://localhost:30481", false},
		{"http://[::1]:30481", true},
		{"https://127.0.0.1:30481", true},
		{"http://192.168.1.31:30481", false},
